/* The Boundary Manager — Calm, human, future-of-work theme: warm cream, sage green, soft teal. */
.boundary-sim-container {
    padding: 28px;
    background: #f4f1ea;
    background-image: linear-gradient(180deg, #f6f3ec 0%, #eef0e9 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2f3a34;
}
.boundary-sim-header {
    background: linear-gradient(135deg, #2f5d50 0%, #3f7a66 100%);
    color: #f3f7f4;
    padding: 32px 36px;
    border-radius: 14px;
    margin-bottom: 24px;
    box-shadow: 0 10px 30px rgba(47,93,80,0.22);
    position: relative;
    overflow: hidden;
}
.boundary-sim-header::after {
    content: "";
    position: absolute;
    right: -40px;
    top: -40px;
    width: 220px;
    height: 220px;
    background: radial-gradient(circle, rgba(255,255,255,0.12) 0%, transparent 70%);
    pointer-events: none;
}
.boundary-sim-header-tag {
    display: inline-block;
    background: rgba(255,255,255,0.16);
    color: #d8eee4;
    padding: 5px 13px;
    border-radius: 20px;
    font-size: 0.74rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin-bottom: 14px;
    font-weight: 700;
    position: relative;
}
.boundary-sim-header h1 {
    font-size: 2.1rem;
    font-weight: 800;
    margin: 0 0 10px 0;
    letter-spacing: -0.01em;
    position: relative;
}
.boundary-sim-subtitle {
    margin: 0;
    font-size: 1.02rem;
    color: #dcebe4;
    max-width: 800px;
    line-height: 1.55;
    position: relative;
}
.boundary-sim-period-counter {
    background: #ffffff;
    border: 1px solid #dfe4dc;
    border-radius: 12px;
    padding: 14px 22px;
    margin-bottom: 20px;
    font-size: 0.95rem;
    color: #6b7a72;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    box-shadow: 0 2px 8px rgba(47,93,80,0.05);
}
.boundary-sim-period-counter span {
    font-weight: 700;
    color: #2f3a34;
}
.boundary-sim-round-name {
    margin-left: 14px;
    color: #3f7a66;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.85rem;
}
.boundary-sim-clock {
    margin-left: auto;
    color: #b9622b !important;
    font-variant-numeric: tabular-nums;
    background: rgba(214,123,58,0.12);
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.85rem;
    font-weight: 700;
}
.boundary-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 18px;
}
.boundary-sim-status-card {
    background: #ffffff;
    border: 1px solid #e1e6df;
    border-radius: 14px;
    padding: 22px 20px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 3px 12px rgba(47,93,80,0.06);
}
.boundary-sim-status-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 24px rgba(47,93,80,0.12);
}
.boundary-sim-card-primary {
    border-top: 5px solid #3f7a66;
    background: linear-gradient(180deg, #eef6f1 0%, #ffffff 100%);
}
.boundary-sim-card-warn {
    border-top: 5px solid #d67b3a;
    background: linear-gradient(180deg, #fbf2ea 0%, #ffffff 100%);
}
.boundary-sim-label {
    color: #7f8c84;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    font-weight: 700;
    margin-bottom: 10px;
}
.boundary-sim-value {
    font-size: 2.5rem;
    font-weight: 800;
    color: #2f3a34;
    line-height: 1;
    margin-bottom: 6px;
    font-variant-numeric: tabular-nums;
}
.boundary-sim-card-primary .boundary-sim-value {
    color: #2f7d5e;
}
.boundary-sim-card-warn .boundary-sim-value {
    color: #c2641f;
}
.boundary-sim-sublabel {
    color: #8c978f;
    font-size: 0.78rem;
}
.boundary-sim-cost-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 10px;
    background: #fdf6ef;
    border: 1px solid #ecd9c6;
    border-left: 5px solid #d67b3a;
    border-radius: 12px;
    padding: 14px 22px;
    margin-bottom: 24px;
}
.boundary-sim-cost-label {
    color: #8a6a4a;
    font-size: 0.9rem;
    font-weight: 600;
}
.boundary-sim-cost-value {
    color: #b9622b;
    font-size: 1.5rem;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}
.boundary-sim-briefing {
    background: #ffffff;
    border: 1px solid #dbe7df;
    border-left: 5px solid #3f7a66;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 24px;
    display: flex;
    gap: 18px;
    align-items: flex-start;
    box-shadow: 0 3px 12px rgba(47,93,80,0.06);
}
.boundary-sim-briefing-icon {
    font-size: 2rem;
    line-height: 1;
    flex-shrink: 0;
}
.boundary-sim-briefing-body {
    flex: 1;
}
.boundary-sim-briefing-title {
    font-size: 1.08rem;
    font-weight: 800;
    color: #2f5d50;
    margin-bottom: 8px;
}
.boundary-sim-briefing-text {
    color: #4a564f;
    line-height: 1.62;
    font-size: 0.95rem;
}
.boundary-sim-briefing-text strong {
    color: #2f7d5e;
}
.boundary-sim-controls {
    background: #ffffff;
    border: 1px solid #e1e6df;
    border-radius: 14px;
    padding: 26px;
    margin-bottom: 24px;
    box-shadow: 0 3px 12px rgba(47,93,80,0.06);
}
.boundary-sim-controls h3 {
    font-size: 1.1rem;
    font-weight: 800;
    color: #2f3a34;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #e6eae3;
}
.boundary-sim-panel {
    margin-bottom: 8px;
}
.boundary-sim-controls label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #44524b;
    margin-bottom: 6px;
    margin-top: 16px;
}
.boundary-sim-controls input[type="number"],
.boundary-sim-controls input[type="text"],
.boundary-sim-controls select {
    width: 100%;
    background-color: #f7f9f6;
    border: 1px solid #cdd6cd;
    color: #2f3a34;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.boundary-sim-controls select option {
    background-color: #ffffff;
    color: #2f3a34;
}
.boundary-sim-controls input[type="number"]:focus,
.boundary-sim-controls input[type="text"]:focus,
.boundary-sim-controls select:focus {
    outline: none;
    border-color: #3f7a66;
    box-shadow: 0 0 0 3px rgba(63,122,102,0.18);
}
.boundary-sim-controls input[type="range"] {
    width: 100%;
    accent-color: #3f7a66;
    margin-top: 8px;
}
.boundary-sim-range-readout {
    font-size: 0.85rem;
    color: #6b7a72;
    margin-top: 6px;
}
.boundary-sim-range-readout span:last-child {
    color: #2f7d5e;
    font-weight: 700;
}
.boundary-sim-controls .btn {
    margin-top: 24px;
    padding: 12px 26px;
    border-radius: 24px;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    border: none;
    transition: background 0.2s ease, transform 0.15s ease;
}
.boundary-sim-controls .btn-primary {
    background: #3f7a66;
    color: #ffffff;
}
.boundary-sim-controls .btn-primary:hover {
    background: #2f5d50;
    transform: translateY(-1px);
}
.boundary-sim-controls .btn-outline-secondary {
    background: transparent;
    color: #6b7a72;
    border: 1px solid #cdd6cd;
    margin-left: 10px;
}
.boundary-sim-controls .btn-outline-secondary:hover {
    background: #eef0e9;
    color: #2f3a34;
}
.boundary-sim-coach {
    background: linear-gradient(135deg, #2f5d50 0%, #3f7a66 100%);
    color: #eef6f1;
    border-radius: 14px;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-left: 5px solid #d67b3a;
    box-shadow: 0 6px 20px rgba(47,93,80,0.18);
}
.boundary-sim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #f0c89e;
    font-weight: 800;
    margin-bottom: 10px;
}
.boundary-sim-coach-body {
    line-height: 1.62;
    font-size: 0.98rem;
    color: #eef6f1;
}
.boundary-sim-coach-body strong {
    color: #ffe6cb;
}
.boundary-sim-history {
    background: #ffffff;
    border: 1px solid #e1e6df;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    overflow-x: auto;
    box-shadow: 0 3px 12px rgba(47,93,80,0.06);
}
.boundary-sim-history h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #2f3a34;
    margin: 0 0 14px 0;
}
.boundary-sim-history table {
    margin-bottom: 0;
    color: #2f3a34;
    width: 100%;
}
.boundary-sim-history table th {
    background: #eef4ef;
    color: #5a6a61;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    font-weight: 700;
    border-bottom: 2px solid #dde6df;
    padding: 10px 12px;
}
.boundary-sim-history table td {
    color: #3d4a43;
    font-size: 0.9rem;
    padding: 10px 12px;
    border-bottom: 1px solid #edf1ec;
}
.boundary-sim-chart {
    background: #ffffff;
    border: 1px solid #e1e6df;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    height: 380px;
    box-shadow: 0 3px 12px rgba(47,93,80,0.06);
}
.boundary-sim-chart h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #2f3a34;
    margin: 0 0 14px 0;
}
.boundary-sim-chart canvas {
    max-height: 300px;
}
@media (max-width: 768px) {
    .boundary-sim-container { padding: 16px; }
    .boundary-sim-header { padding: 24px 22px; }
    .boundary-sim-header h1 { font-size: 1.5rem; }
    .boundary-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .boundary-sim-value { font-size: 1.9rem; }
    .boundary-sim-period-counter { flex-wrap: wrap; }
    .boundary-sim-clock { margin-left: 0; width: 100%; margin-top: 6px; text-align: center; }
    .boundary-sim-round-name { margin-left: 0; }
    .boundary-sim-cost-bar { flex-direction: column; align-items: flex-start; }
}


/* FIX v1.1.0 — completion / debrief screen */
.bm-completion { padding: 10px 6px; text-align: center; }
.bm-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.bm-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.bm-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.bm-completion-score strong { color: #0891b2; }
.bm-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.bm-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 100px; }
.bm-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.bm-completion-metric strong { font-size: 16px; color: #0f172a; }
.bm-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.bm-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #ecfeff; border-left: 3px solid #0891b2; border-radius: 4px; color: #1e293b; font-size: 13px; }

