(function() {
    'use strict';

    class BoundaryAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Boundary Manager`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Concept numbers reference card.
            this.REPLACEMENT_COST = 65000;   // € per engineer lost
            this.CLIENT_ARR = 4200000;       // € client at risk
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    wellbeing: 38,        // inverse of work-family conflict; bottom-quartile start
                    delivery: 55,         // confidence on the €4.2M release
                    retention: 62,        // attrition pressure (LOWER is better)
                    modeling: 45,         // FSSB / manager role-modelling
                    cost: 0,              // € accumulated cost of inaction / mis-steps
                    departures: 0,        // additional engineers lost
                    releaseMissed: false,
                    diagnosedStructural: false,
                    wellbeingHistory: [38],
                    deliveryHistory: [55],
                    retentionHistory: [62],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    diag: `structural`,
                    lens: `norms`,
                    costSeriousness: 50,
                    norm: `buffer`,
                    exception: `defined`,
                    stopPct: 60,
                    policy: `output`,
                    caseDecision: `grant_covered`,
                    fairness: `transparent`,
                    frame: `complementary`,
                    metrics: `balanced`,
                    modelCommit: 60,
                    review: `yes`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagInput`);
                const ln = document.getElementById(`lensInput`);
                const cs = document.getElementById(`costSeriousnessInput`);
                if (dg) decisions.diag = dg.value;
                if (ln) decisions.lens = ln.value;
                if (cs) decisions.costSeriousness = parseInt(cs.value, 10);
                if (!Number.isFinite(decisions.costSeriousness) || decisions.costSeriousness < 0 || decisions.costSeriousness > 100) {
                    warn(`warn_cost_range`); return false;
                }
            } else if (round === 2) {
                const nm = document.getElementById(`normInput`);
                const ex = document.getElementById(`exceptionInput`);
                const sp = document.getElementById(`stopPctInput`);
                if (nm) decisions.norm = nm.value;
                if (ex) decisions.exception = ex.value;
                if (sp) decisions.stopPct = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.stopPct) || decisions.stopPct < 0 || decisions.stopPct > 100) {
                    warn(`warn_stop_range`); return false;
                }
            } else if (round === 3) {
                const pl = document.getElementById(`policyInput`);
                const ca = document.getElementById(`caseInput`);
                const fa = document.getElementById(`fairnessInput`);
                if (pl) decisions.policy = pl.value;
                if (ca) decisions.caseDecision = ca.value;
                if (fa) decisions.fairness = fa.value;
            } else if (round === 4) {
                const fr = document.getElementById(`frameInput`);
                const mt = document.getElementById(`metricsInput`);
                const mc = document.getElementById(`modelCommitInput`);
                const rv = document.getElementById(`reviewInput`);
                if (fr) decisions.frame = fr.value;
                if (mt) decisions.metrics = mt.value;
                if (mc) decisions.modelCommit = parseInt(mc.value, 10);
                if (rv) decisions.review = rv.value;
                if (!Number.isFinite(decisions.modelCommit) || decisions.modelCommit < 0 || decisions.modelCommit > 100) {
                    warn(`warn_model_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let wbDelta = 0, delDelta = 0, retDelta = 0, modDelta = 0;
            let costAdded = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: structural vs individual. (Common Error 1 / first decision-tree branch.)
                if (d.diag === `structural`) {
                    wbDelta += 8; retDelta -= 6; ds.diagnosedStructural = true;
                    coachKey = `coach_r1_structural`;
                    summaryKey = `sum_r1_good`;
                } else if (d.diag === `individual`) {
                    // Resilience-workshop trap: looks like action, changes nothing structural.
                    wbDelta -= 6; retDelta += 6; costAdded += 8000;
                    coachKey = `coach_r1_individual`;
                    summaryKey = `sum_r1_weak`;
                } else if (d.diag === `workload`) {
                    wbDelta += 1; retDelta += 1; coachKey = `coach_r1_workload`; summaryKey = `sum_r1_weak`;
                } else if (d.diag === `legal`) {
                    wbDelta -= 2; retDelta += 2; coachKey = `coach_r1_legal`; summaryKey = `sum_r1_weak`;
                }
                // Lens: naming the absent shared norm as the DRIVER (not just the symptom) sharpens the fix.
                if (d.lens === `norms`) { wbDelta += 4; retDelta -= 2; }
                else { /* connectivity = symptom-level */ wbDelta -= 1; }
                // Taking the cost of inaction seriously focuses the whole team; ignoring it under-resources the fix.
                if (d.costSeriousness >= 60) { retDelta -= 3; }
                else if (d.costSeriousness <= 25) { retDelta += 3; costAdded += 4000; }
            } else if (round === 2) {
                // After-hours connectivity norm: reconcile the right to disconnect with a real midnight client.
                // (Common Error 2 / second decision-tree branch.)
                switch (d.norm) {
                    case `buffer`:
                        wbDelta += 14; delDelta += 6; retDelta -= 8; coachKey = `coach_r2_buffer`; break;
                    case `tiered`:
                        wbDelta += 12; delDelta += 4; retDelta -= 6; coachKey = `coach_r2_tiered`; break;
                    case `async`:
                        wbDelta += 11; delDelta += 2; retDelta -= 5; coachKey = `coach_r2_async`; break;
                    case `hard`:
                        // Wishful policy that ignores the client → it collapses on contact; delivery suffers.
                        wbDelta += 6; delDelta -= 14; retDelta -= 2; costAdded += 30000;
                        coachKey = `coach_r2_hard`; break;
                    case `none`:
                        // Status quo: the structural norm persists, exhaustion continues.
                        wbDelta -= 8; retDelta += 8; costAdded += 12000;
                        coachKey = `coach_r2_none`; break;
                }
                // The escalation exception is what lets a boundary survive Monday with a real client.
                if (d.exception === `defined`) { delDelta += 6; wbDelta += 3; }
                else if (d.exception === `manager`) { delDelta += 1; wbDelta -= 2; }
                else if (d.exception === `open`) {
                    // No exception at all: the client breaks the rule and the team learns the rule is fake.
                    delDelta -= 8; wbDelta -= 4; coachKey = (d.norm === `hard`) ? `coach_r2_hard` : `coach_r2_noexc`;
                }
                // Deciding what to STOP doing (not just what to add) is where boundaries become real.
                if (d.stopPct >= 50) { wbDelta += Math.round((d.stopPct - 50) / 8); }
                else { wbDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_nostop` : coachKey; }
                summaryKey = (d.norm === `buffer` || d.norm === `tiered` || d.norm === `async`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Flexibility policy + the live case + fairness. (Common Error 3 / third decision-tree branch.)
                // A policy is only as good as the consistency & fairness of its application.
                if (d.policy === `output`) { wbDelta += 6; delDelta += 4; }
                else if (d.policy === `compressed`) { wbDelta += 4; delDelta += 1; }
                else if (d.policy === `core`) { wbDelta += 3; delDelta += 2; }
                else if (d.policy === `discretion`) {
                    // Case-by-case in private breeds perceived unfairness (i-deals risk).
                    wbDelta -= 2; retDelta += 4; coachKey = `coach_r3_discretion`;
                }

                switch (d.caseDecision) {
                    case `grant_covered`:
                        wbDelta += 10; retDelta -= 10; delDelta += 2; coachKey = `coach_r3_grant_covered`; break;
                    case `grant_dump`:
                        // Solves one boundary by breaking two others on already-stretched teammates.
                        wbDelta -= 10; retDelta += 8; delDelta -= 2; costAdded += 20000;
                        coachKey = `coach_r3_grant_dump`; break;
                    case `deny`:
                        // Signals flexibility is only for emergencies / not real; she likely leaves.
                        wbDelta -= 8; retDelta += 14; costAdded += this.REPLACEMENT_COST;
                        coachKey = `coach_r3_deny`; break;
                    case `defer`:
                        wbDelta -= 5; retDelta += 9; costAdded += 15000;
                        coachKey = `coach_r3_defer`; break;
                }

                // Fairness design determines whether granting relocates the burden or shares it well.
                if (d.fairness === `transparent`) { wbDelta += 6; retDelta -= 4; modDelta += 4; }
                else if (d.fairness === `quiet`) {
                    wbDelta -= 4; retDelta += 4; coachKey = `coach_r3_quiet`;
                } else if (d.fairness === `none`) {
                    wbDelta -= 6; retDelta += 6;
                    if (d.caseDecision === `grant_covered`) coachKey = `coach_r3_nocover`;
                }
                // Coverage promise without a fairness mechanism is half-empty (gate).
                if (d.caseDecision === `grant_covered` && d.fairness === `none`) {
                    wbDelta = Math.round(wbDelta * 0.6);
                }
                summaryKey = (d.caseDecision === `grant_covered` && d.fairness === `transparent`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Integrate output + wellbeing; commit metrics; model the boundary. (Common Errors 4 & 5.)
                if (d.frame === `complementary`) { wbDelta += 8; delDelta += 10; retDelta -= 8; coachKey = `coach_r4_complementary`; }
                else if (d.frame === `sequence`) {
                    // "Protect wellbeing after the release" — the attrition arrives before "after".
                    wbDelta -= 6; delDelta += 4; retDelta += 8; costAdded += 25000;
                    coachKey = `coach_r4_sequence`;
                } else if (d.frame === `tradeoff`) {
                    // Output must win: push harder, lose two more, blow the NEXT release.
                    wbDelta -= 12; delDelta += 2; retDelta += 14; costAdded += this.REPLACEMENT_COST;
                    coachKey = `coach_r4_tradeoff`;
                }

                if (d.metrics === `balanced`) { wbDelta += 4; delDelta += 2; retDelta -= 3; }
                else if (d.metrics === `delivery`) { wbDelta -= 3; }
                else if (d.metrics === `wellbeing`) { delDelta -= 3; }

                // Manager modelling (FSSB): the single strongest lever — a manager who messages at 22:15
                // teaches the real rule regardless of the charter text.
                modDelta += Math.round((d.modelCommit - 45) / 4);
                if (d.modelCommit >= 75) { wbDelta += 8; retDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_model_strong` : coachKey; }
                else if (d.modelCommit <= 30) { wbDelta -= 8; retDelta += 6; modDelta -= 6; coachKey = `coach_r4_model_weak`; }

                if (d.review === `yes`) { retDelta -= 3; modDelta += 3; }
                else { wbDelta -= 2; }
                summaryKey = (d.frame === `complementary` && d.modelCommit >= 60) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Manager modelling amplifies how well wellbeing & retention moves actually register:
            // family-supportive WORDS with always-on MODELLING under-deliver (FSSB primacy).
            const fssbFactor = 0.7 + (ds.modeling / 100) * 0.5; // 0.7 .. 1.2
            if (wbDelta > 0) wbDelta = Math.round(wbDelta * fssbFactor);
            if (retDelta < 0) retDelta = Math.round(retDelta * fssbFactor);

            // Apply deltas (wellbeing/delivery/modeling: higher better; retention: lower better).
            ds.wellbeing = Math.max(0, Math.min(100, ds.wellbeing + wbDelta));
            ds.delivery = Math.max(0, Math.min(100, ds.delivery + delDelta));
            ds.retention = Math.max(0, Math.min(100, ds.retention + retDelta));
            ds.modeling = Math.max(0, Math.min(100, ds.modeling + modDelta));

            // Cost of inaction accrues from mis-steps; high retention risk also implies expected attrition cost.
            ds.cost += costAdded;

            // Additional departures: sustained high retention risk converts to a real €65k loss.
            if (ds.retention >= 80 && ds.departures < 2) {
                ds.departures += 1;
                ds.cost += this.REPLACEMENT_COST;
            }
            // A wishful or collapsed norm with low delivery at the end risks missing the release.
            if (round === 4 && ds.delivery < 45) {
                ds.releaseMissed = true;
            }

            ds.wellbeingHistory.push(ds.wellbeing);
            ds.deliveryHistory.push(ds.delivery);
            ds.retentionHistory.push(ds.retention);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A — expose the composite (clamped 0-100) on the reporting paths.
            var _c = Math.max(0, Math.min(100, Math.round(ds.wellbeing * 0.30 + ds.delivery * 0.28 + (100 - ds.retention) * 0.24 + ds.modeling * 0.18)));
            ds.score = _c;
            ds.performance = { overallScore: _c };
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                wellbeing: ds.wellbeing,
                wbDelta: wbDelta,
                delivery: ds.delivery,
                delDelta: delDelta,
                retention: ds.retention,
                retDelta: retDelta,
                modeling: ds.modeling,
                cost: ds.cost,
                departures: ds.departures,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

