        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.score != null) ? summary.score : 0;
            var grade = summary.gradeKey ? t(summary.gradeKey) : '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="bm-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var metrics = ''
                + metric(t('comp_wb_label'), (summary.wellbeing != null ? summary.wellbeing : '-'))
                + metric(t('comp_del_label'), (summary.delivery != null ? summary.delivery : '-'))
                + metric(t('comp_ret_label'), (summary.retention != null ? summary.retention : '-'))
                + metric(t('comp_mod_label'), (summary.modeling != null ? summary.modeling : '-'))
                + metric(t('comp_dep_label'), (summary.departures != null ? summary.departures : '-'));
            return ''
                + '<div class="bm-completion">'
                +   '<div class="bm-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="bm-completion-verdict">' + grade + '</div>'
                +   '<div class="bm-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="bm-completion-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="bm-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const wb = ds.wellbeing, del = ds.delivery, ret = ds.retention, mod = ds.modeling;

            // Composite: wellbeing + delivery + modelling reward, retention risk penalises.
            const composite = Math.round(wb * 0.30 + del * 0.28 + (100 - ret) * 0.24 + mod * 0.18);
            const delivered = del >= 55 && !ds.releaseMissed;
            const sustainable = delivered && wb >= 58 && ret <= 50;

            let performance = `Burning Out`;
            if (sustainable && composite >= 70) performance = `Boundary Architect`;
            else if (delivered && composite >= 56) performance = `Balanced`;
            else if (composite >= 42) performance = `Fragile`;

            const insights = [];
            if (sustainable) insights.push(window.mySimulation.t(`insight_sustainable`));
            else if (delivered) insights.push(window.mySimulation.t(`insight_delivered`));
            else insights.push(window.mySimulation.t(`insight_frayed`));

            if (ds.releaseMissed) insights.push(window.mySimulation.t(`insight_missed`));
            if (ds.departures > 0) insights.push(window.mySimulation.t(`insight_departures`));
            if (!ds.diagnosedStructural) insights.push(window.mySimulation.t(`insight_individual`));
            if (mod < 45) insights.push(window.mySimulation.t(`insight_modeling`));
            if (ret >= 70) insights.push(window.mySimulation.t(`insight_retention`));

            const _sc = Math.max(0, Math.min(100, composite));
            const _gk = (sustainable && composite >= 70) ? 'grade_architect' : (delivered && composite >= 56) ? 'grade_balanced' : (composite >= 42) ? 'grade_fragile' : 'grade_burnout';
            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                window.mySimulation.state.domainState.score = _sc;
                window.mySimulation.state.domainState.performance = { overallScore: _sc, grade: window.mySimulation.t(_gk) };
            }
            return {
                score: _sc,
                gradeKey: _gk,
                wellbeing: wb,
                delivery: del,
                retention: ret,
                modeling: mod,
                cost: ds.cost,
                departures: ds.departures,
                composite: composite,
                performance: performance,
                delivered: delivered,
                sustainable: sustainable,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.releaseMissed) return window.mySimulation.t(`hint_missed`);
            if (results.retDelta > 6) return window.mySimulation.t(`hint_retention`);
            if (!ds.diagnosedStructural && state.currentPeriod >= 2) return window.mySimulation.t(`hint_structural`);
            if (ds.modeling < 40 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_modeling`);
            if (ds.wellbeing >= 65 && ds.delivery >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

